render_technologies_used([{'name': 'Semantic View', 'description': 'A first-class object describing tables, relationships, facts, dimensions and metrics in business terms.', 'icon': 'description'}, {'name': 'Cortex Analyst', 'description': 'Text-to-SQL that uses the semantic view to answer natural-language questions.', 'icon': 'chat'}, {'name': 'Verified Queries', 'description': 'Trusted question/SQL pairs that improve accuracy for common questions.', 'icon': 'verified'}])

render_prompt('Prompt 2.1', 'Generate the semantic view', 'Create a semantic view called AIRLINE_OPS_SV in AIRLINE_OPS.OPS on top of the booking, flight, passenger and airport tables. Join the airport table twice, once for origin and once for destination.\n\nI want to be able to slice by date, cabin, channel, booking status, Aeroplan tier, passenger, aircraft, flight status, route and airport (city, country, region). The main metrics are revenue, bookings, flights, passengers, average fare, on-time % (delay of 15 min or less), cancellation rate and load factor. Load factor should come from the flight table only, since the bookings are just a sample.\n\nA few rules:\n- This year is 2026 and last year is 2025. Winter is Dec to Feb, summer is Jun to Aug.\n- Revenue only counts FLOWN and NO_SHOW bookings.\n- Airport stats are by departure airport unless I ask about arrivals.\n- Passenger questions go by passenger ID, not name. Include email and birth date columns\n- Hubs are YUL, YYZ, YVR and YYC.\n\nRun it and show me DESCRIBE SEMANTIC VIEW.')

render_prompt('Snowsight', 'Open semantic view in Workspaces', '1. In Catalog Explorer, in the AIRLINE_OPS database, expand the OPS schema, then click on Semantic views.\n2. Notice that your organization can certify semantic views and filter to show only certified semantic views.\n3. Click on AIRLINE_OPS_SV.\n4. Review the Overview tab to see the logical tables, columns and relationships.\n5. Click on Lineage to review how tables are related to each other.\n6. Then click on the button with three dots in the right corner and click on Open in Workspaces.\n7. Review the UI: the main editor window with the Visual, YAML and Diagram views, and the side pane with the Suggestions, Playground, Monitoring and Evaluations panes. Review the Pull and Deploy buttons by clicking on them.\n8. Click on the Playground tab and click Explain this dataset. Then click on a suggested question.\n9. Click +Add to verified query.\n10. Review the Monitoring tab. You might need to refresh the page to see entries.\n11. Then click on the Deploy button in the right corner.', caption='Follow these steps in Snowsight', key='Snowsight 2')

render_prompt('Prompt 2.2', 'Test with natural-language questions', 'Using Cortex Analyst on AIRLINE_OPS.OPS.AIRLINE_OPS_SV, answer these questions:\n1. What was total revenue this year vs last year by month?\n2. Which 5 routes have the highest revenue in 2026?\n3. What is on-time performance by hub airport (YUL, YYZ, YVR, YYC) for last winter?\n4. What share of revenue comes from Business class by Aeroplan tier?\n5. What was the load factor by month this year vs last year?')
render_explanation("What this prompt does", 'Cortex Analyst turns each question into SQL against the semantic view. Review each answer and its SQL: is revenue limited to FLOWN and NO_SHOW bookings, are "this year" and "last year" mapped to 2026 and 2025, is winter Dec to Feb, are hub stats by departure airport, and does load factor come from the flight table? Once an answer is correct, it is a good candidate to save as a verified query.')

render_key_concepts([{'term': 'Semantic view', 'definition': 'A Snowflake object that maps physical tables to business concepts: logical tables, relationships, dimensions, facts and metrics, plus descriptions, synonyms and business rules. Cortex Analyst reads it to generate SQL.'}, {'term': 'Facts vs metrics', 'definition': 'Facts are row-level numeric values (fare, delay minutes, seats); metrics are aggregations (SUM, AVG, ratios) defined once and reused, so every question computes revenue or load factor the same way.'}, {'term': 'Role-playing dimension', 'definition': 'One dimension table joined twice with different meanings, like origin and destination airport.'}, {'term': 'Business rules', 'definition': 'Definitions such as "this year = 2026", "revenue counts FLOWN and NO_SHOW only" or "hubs are YUL, YYZ, YVR, YYC" that belong in the semantic view, so every question gets the same answer regardless of who asks.'}, {'term': 'Verified queries', 'definition': 'Question/SQL pairs reviewed by a person and stored in the semantic view. They are the main lever for accuracy and trust: Cortex Analyst uses them as examples for similar questions, answers that match one are flagged as verified, and they capture tricky logic (YoY comparisons, ratios, sample-vs-full data) that is easy to get wrong. Add one whenever you confirm a correct answer to an important question.'}])

render_what_you_built(['AIRLINE_OPS_SV semantic view with business rules', 'Explored it in Workspaces (Overview, Lineage, Playground, Monitoring)', 'A verified query added from the Playground', 'Tested revenue, route, on-time, cabin and load factor questions'])
